/*\n  # Fix Kiosk Contact Creation RLS Policy\n\n  1. Changes\n    - Drop the existing overly restrictive anonymous contact creation policy\n    - Add a new simplified policy that allows kiosk submissions\n    - The new policy requires minimal fields: email, contact_name OR (first_name AND last_name), and phone\n    - This allows the tradeshow kiosk to create contacts without full address information\n\n  2. Security\n    - Still restricts anonymous users to only INSERT (cannot read/update/delete)\n    - Requires essential contact information (email, name, phone)\n    - Requires contact_type = 'person' for consistency\n*/\n\n-- Drop the old restrictive policy\nDROP POLICY IF EXISTS "Anonymous users can create contacts for VIP signup or kiosk" ON contacts

\n\n-- Create a new, simplified policy for kiosk and VIP signups\nCREATE POLICY "Anonymous users can create contacts for kiosk and VIP"\n  ON contacts\n  FOR INSERT\n  TO anon\n  WITH CHECK (\n    -- Require email, phone, and contact type\n    email IS NOT NULL\n    AND phone IS NOT NULL\n    AND contact_type = 'person'\n    AND (\n      -- Either contact_name is provided\n      contact_name IS NOT NULL\n      OR\n      -- Or both first_name and last_name are provided\n      (first_name IS NOT NULL AND last_name IS NOT NULL)\n    )\n  )

\n
